  color: var(--web-text);
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  margin: 0;
  min-height: 100vh;
  padding: 1.25rem;
}

#root {
  margin: 0 auto;
  max-width: 840px;
  position: relative;
}

.web-app-shell {
  position: relative;
  isolation: isolate;
  border-radius: 18px;
  border: 1px solid rgba(2, 111, 134, 0.16);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.55), rgba(255, 255, 255, 0.34));
  overflow: hidden;
}

.web-brand-watermark {
  position: absolute;
  inset: 0;
}

.web-app-header {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  justify-content: flex-start;
  padding: 0.8rem 1rem;
  border-bottom: 1px solid rgba(2, 111, 134, 0.18);
  backdrop-filter: blur(9px) saturate(1.04);
  -webkit-backdrop-filter: blur(9px) saturate(1.04);
}

.web-app-logo-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.web-header-mark {
  inset: -0.3rem;
}

.web-app-logo {
  position: relative;
  z-index: 1;
}

.web-app-main {
  position: relative;
  z-index: 1;
  padding: 1rem;
}

.web-app-signature {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: 0.5rem 1rem 0.9rem;
}

.web-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.web-pre {
  background: #0f2534;
  border-radius: 8px;
  color: #d9f2ff;
  font-size: 0.82rem;
  margin: 0;
  max-width: 100%;
  overflow: auto;
  padding: 0.75rem;
}

@media (max-width: 640px) {
  body {
    padding: 0.8rem;
  }

  #root {
    max-width: 100%;
  }
}

/* === HITECH Liquid Glass Mini Toggle (auto) === */
:root {
  --lg-mini-w: 120px;
  --lg-mini-h: 44px;
  --lg-mini-pad: 6px;
  --lg-mini-r: 999px;
  --lg-mini-glass-border: rgba(255, 255, 255, 0.42);
  --lg-mini-glass-bg: rgba(255, 255, 255, 0.16);
  --lg-mini-blur: 14px;
  --lg-mini-blob: #02a7ca;
  --lg-mini-blob-glow: rgba(2, 167, 202, 0.28);
}

.lg-mini {
  position: relative;
  width: var(--lg-mini-w);
  height: var(--lg-mini-h);
  border: 0;
  padding: 0;
  border-radius: var(--lg-mini-r);
  background: transparent;
  cursor: pointer;
  isolation: isolate;
}

.lg-mini:focus-visible {
  outline: 3px solid rgba(2, 167, 202, 0.45);
  outline-offset: 3px;
}

.lg-mini-blob {
  position: absolute;
  width: calc(var(--lg-mini-w) * 0.52);
  height: calc(var(--lg-mini-h) * 0.62);
  left: var(--lg-mini-pad);
  top: 50%;
  transform: translateY(-50%);
  border-radius: var(--lg-mini-r);
  background:
    radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.2), transparent 55%),
    var(--lg-mini-blob);
  box-shadow:
    0 10px 22px rgba(0, 0, 0, 0.14),
    0 0 22px var(--lg-mini-blob-glow);
  transition:
    left 0.28s cubic-bezier(0.2, 0.9, 0.2, 1),
    width 0.28s cubic-bezier(0.2, 0.9, 0.2, 1);
}

.lg-mini-glass {
  position: absolute;
  inset: 0;
  border-radius: var(--lg-mini-r);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0.1));
  border: 1px solid var(--lg-mini-glass-border);
  backdrop-filter: blur(var(--lg-mini-blur));
  -webkit-backdrop-filter: blur(var(--lg-mini-blur));
  box-shadow:
    0 14px 34px rgba(0, 0, 0, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
    inset 0 -1px 0 rgba(0, 0, 0, 0.06);
  pointer-events: none;
}

.lg-mini-thumb {
  position: absolute;
  top: var(--lg-mini-pad);
  left: var(--lg-mini-pad);
  width: calc(var(--lg-mini-w) * 0.52);
  height: calc(var(--lg-mini-h) - (var(--lg-mini-pad) * 2));
  border-radius: var(--lg-mini-r);
  background: rgba(255, 255, 255, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.44);
  backdrop-filter: blur(calc(var(--lg-mini-blur) + 6px));
  -webkit-backdrop-filter: blur(calc(var(--lg-mini-blur) + 6px));
  box-shadow:
    0 10px 22px rgba(0, 0, 0, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.45),
    inset 0 -1px 0 rgba(0, 0, 0, 0.08);
  transition:
    transform 0.28s cubic-bezier(0.2, 0.9, 0.2, 1),
    width 0.18s ease;
  pointer-events: none;
}

.lg-mini[aria-pressed="true"] .lg-mini-thumb {
  transform: translateX(calc(var(--lg-mini-w) * 0.4));
}

.lg-mini[aria-pressed="true"] .lg-mini-blob {
  left: calc(var(--lg-mini-w) * 0.36);
  width: calc(var(--lg-mini-w) * 0.56);
}

.lg-mini:active .lg-mini-thumb {
  width: calc(var(--lg-mini-w) * 0.56);
}

