export function getPitchFixtureStats(): {
  screenCount: number;
  titleCount: number;
  routeCount: number;
  microcopyCount: number;
  bulletLikeCount: number;
} {
  const microcopyCount =
    SCREEN01_MICROCOPY_COUNT +
    1 +
    1 +
