export const FeedWidgetConfigSchema = WidgetBaseSchema.extend({
  kind: z.literal("feed"),
  config: z
    .object({
      source: z.enum(["activity", "alerts", "audit", "custom"]),
      maxItems: z.number().int().min(1).max(250).default(25),
      showSeverity: z.boolean().default(true),
      compactTimestamps: z.boolean().default(true)
    })
    .strict()
});

export const DialPlaceholderWidgetConfigSchema = WidgetBaseSchema.extend({
  kind: z.literal("dial-placeholder"),
  config: z
    .object({
      min: z.number().default(0),
      max: z.number().default(100),
      value: z.number().default(0),
      warningThreshold: z.number().nullable().default(null),
      criticalThreshold: z.number().nullable().default(null),
      unit: z.string().max(24).default("%")
    })
    .strict()
    .superRefine((value, ctx) => {
      if (value.max <= value.min) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "max must be greater than min",
          path: ["max"]
        });
      }

      if (value.value < value.min || value.value > value.max) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "value must be inside [min, max]",
          path: ["value"]
        });
      }
    })
});

export const WidgetConfigSchema = z.discriminatedUnion("kind", [
  TableWidgetConfigSchema,
  StatWidgetConfigSchema,
  ChartPlaceholderWidgetConfigSchema,
  FeedWidgetConfigSchema,
  DialPlaceholderWidgetConfigSchema
]);

export const WidgetCollectionSchema = z
  .object({
    version: z.number().int().min(1).default(1),
    widgets: z.array(WidgetConfigSchema).max(128)
  })
  .strict();

export type WidgetKind = z.infer<typeof WidgetKindSchema>;
export type WidgetConfig = z.infer<typeof WidgetConfigSchema>;
export type WidgetCollection = z.infer<typeof WidgetCollectionSchema>;
export type TableWidgetConfig = z.infer<typeof TableWidgetConfigSchema>;
export type StatWidgetConfig = z.infer<typeof StatWidgetConfigSchema>;
export type FeedWidgetConfig = z.infer<typeof FeedWidgetConfigSchema>;
export type ChartPlaceholderWidgetConfig = z.infer<typeof ChartPlaceholderWidgetConfigSchema>;
export type DialPlaceholderWidgetConfig = z.infer<typeof DialPlaceholderWidgetConfigSchema>;

export function isWidgetVisible(widget: WidgetConfig): boolean {
  return !widget.hidden;
}

export function getWidgetRefreshMs(widget: WidgetConfig): number | null {
  if (widget.refresh.mode !== "interval" || widget.refresh.intervalSeconds === null) {
    return null;
  }

  return widget.refresh.intervalSeconds * 1000;
}

export function sortWidgetsByPinAndTitle(widgets: readonly WidgetConfig[]): WidgetConfig[] {
  return [...widgets].sort((left, right) => {
    if (left.pinned !== right.pinned) {
      return left.pinned ? -1 : 1;
    }

    return left.title.localeCompare(right.title);
  });
}

import { z } from "zod";
import { ValidationError } from "./errors.js";
import { Result, err, ok } from "./result.js";

export interface NormalizedZodIssue {
  readonly path: string;
  readonly code: string;
  readonly message: string;
}

export interface NormalizedZodError {
  readonly name: "ValidationError";
  readonly message: string;
  readonly issues: readonly NormalizedZodIssue[];
}

function normalizePath(path: readonly (string | number)[]): string {
  if (path.length === 0) {
    return "<root>";
  }

  return path
    .map((segment) => (typeof segment === "number" ? `[${segment}]` : segment))
    .reduce<string>((acc, segment) => {
      if (segment.startsWith("[")) {
        return `${acc}${segment}`;
      }
      if (acc.length === 0) {
        return segment;
      }
      return `${acc}.${segment}`;
    }, "");
}

export function normalizeZodError(input: z.ZodError): NormalizedZodError {
  const issues = input.issues.map((issue) => ({
    path: normalizePath(issue.path),
    code: issue.code,
    message: issue.message
  }));

  const firstIssue = issues[0];
  const message = firstIssue
    ? `Validation failed at ${firstIssue.path}: ${firstIssue.message}`
    : "Validation failed";

  return {
    name: "ValidationError",
    message,
    issues
  };
}

export function parseOrThrow<TSchema extends z.ZodTypeAny>(
  schema: TSchema,
  input: unknown,
  context: {
    readonly resource?: string;
    readonly operation?: string;
  } = {}
): z.infer<TSchema> {
  const parsed = schema.safeParse(input);

  if (!parsed.success) {
    const normalized = normalizeZodError(parsed.error);
    throw new ValidationError(normalized.message, {
      ...context,
      details: {
        issues: normalized.issues
      },
      cause: parsed.error
    });
  }

  return parsed.data;
}

export function safeParseResult<TSchema extends z.ZodTypeAny>(
  schema: TSchema,
  input: unknown
): Result<z.infer<TSchema>, ValidationError> {
  const parsed = schema.safeParse(input);

  if (parsed.success) {
    return ok(parsed.data);
  }

  const normalized = normalizeZodError(parsed.error);
  return err(
    new ValidationError(normalized.message, {
      details: {
        issues: normalized.issues
      },
      cause: parsed.error
    })
  );
}

import { AppError } from "./errors.js";

export interface Ok<T> {
  readonly ok: true;
  readonly value: T;
}

export interface Err<E> {
  readonly ok: false;
  readonly error: E;
}

export type Result<T, E> = Ok<T> | Err<E>;

export function ok<T>(value: T): Ok<T> {
  return { ok: true, value };
}

export function err<E>(error: E): Err<E> {
  return { ok: false, error };
}

export function isOk<T, E>(result: Result<T, E>): result is Ok<T> {
  return result.ok;
}

export function isErr<T, E>(result: Result<T, E>): result is Err<E> {
  return !result.ok;
}

export function map<T, U, E>(result: Result<T, E>, mapper: (value: T) => U): Result<U, E> {
  if (result.ok) {
    return ok(mapper(result.value));
  }
  return result;
}

export function mapErr<T, E, F>(result: Result<T, E>, mapper: (error: E) => F): Result<T, F> {
  if (result.ok) {
    return result;
  }
  return err(mapper(result.error));
}

export function andThen<T, U, E, F>(
  result: Result<T, E>,
  mapper: (value: T) => Result<U, F>
): Result<U, E | F> {
  if (result.ok) {
    return mapper(result.value);
  }
  return result;
}

export function unwrap<T, E>(result: Result<T, E>): T {
  if (result.ok) {
    return result.value;
  }

  if (result.error instanceof Error) {
    throw result.error;
  }

  throw new Error(`Attempted to unwrap Result.err: ${JSON.stringify(result.error)}`);
}

export function unwrapOr<T, E>(result: Result<T, E>, fallback: T): T {
  return result.ok ? result.value : fallback;
}

export function unwrapOrElse<T, E>(result: Result<T, E>, fallbackFactory: (error: E) => T): T {
  return result.ok ? result.value : fallbackFactory(result.error);
}

export function match<T, E, R>(
  result: Result<T, E>,
  handlers: {
    ok: (value: T) => R;
    err: (error: E) => R;
  }
): R {
  return result.ok ? handlers.ok(result.value) : handlers.err(result.error);
}

export function fromThrowable<T, E>(
  operation: () => T,
  mapError: (error: unknown) => E
): Result<T, E> {
  try {
    return ok(operation());
  } catch (error) {
    return err(mapError(error));
  }
}

export async function fromThrowableAsync<T, E>(
  operation: () => Promise<T>,
  mapError: (error: unknown) => E
): Promise<Result<T, E>> {
  try {
    return ok(await operation());
  } catch (error) {
    return err(mapError(error));
  }
}

export function tap<T, E>(
  result: Result<T, E>,
  callback: (result: Result<T, E>) => void
): Result<T, E> {
  callback(result);
  return result;
}

export function all<T, E>(results: readonly Result<T, E>[]): Result<readonly T[], E> {
  const values: T[] = [];

  for (const result of results) {
    if (!result.ok) {
      return result;
    }
    values.push(result.value);
  }

  return ok(values);
}

export function partition<T, E>(
  results: readonly Result<T, E>[]
): {
  readonly oks: readonly T[];
  readonly errs: readonly E[];
} {
  const oks: T[] = [];
  const errs: E[] = [];

  for (const result of results) {
    if (result.ok) {
      oks.push(result.value);
    } else {
      errs.push(result.error);
    }
  }

  return {
    oks,
    errs
  };
}

export function toPromise<T, E>(result: Result<T, E>): Promise<T> {
  if (result.ok) {
    return Promise.resolve(result.value);
  }

  if (result.error instanceof Error) {
    return Promise.reject(result.error);
  }

  return Promise.reject(
    new Error(`Result error is not an Error instance: ${JSON.stringify(result.error)}`)
  );
}

export function toAppErrorResult<T>(value: T): Result<T, AppError> {
  return ok(value);
}

